No integer of multiplicity $5$, $7$, or $\ge 9$ is known. Singmaster conjectured that $N$ is
bounded; the strongest unconditional bounds available are of the shape
$N(t) = O(\log t/\log\log t)$.

\subsection{Contributions}

We prove five interlocking families of unconditional results: a smoothness hierarchy
(Section~\ref{sec:smooth}); a density-zero counting bound for the exceptional set
(Section~\ref{sec:density}); a factor-two sharpening of the elementary logarithmic bound
(Section~\ref{sec:log}); sharp minimal thresholds for small multiplicities
(Section~\ref{sec:thresholds}); and the complete classification of adjacent repetitions
(Section~\ref{sec:adjacent}).

Throughout, $F_0 = 0$, $F_1 = 1$, $F_{a+2} = F_a + F_{a+1}$ are the Fibonacci numbers, and
$L_0 = 2$, $L_1 = 1$, $L_{a+2} = L_a + L_{a+1}$ the Lucas numbers.

\section{Definitions and the reflection decomposition}

\begin{definition}[Occurrences and multiplicity]
For $t \ge 2$ set
$\Occ(t) = \{(n,k) \in \NN^2 : k \le n,\ \binom{n}{k} = t\}$ and $N(t) = \#\Occ(t)$.
The set is finite, since $\binom{n}{k} = t$ with $1 \le k \le n-1$ forces $n \le t$.
\end{definition}

\begin{definition}[Position types]
An occurrence $(n,k)$ is \emph{boundary} if $k \in \{0,1,n-1,n\}$; \emph{central} if $n = 2k$
and $k \ge 2$; \emph{left-interior} if $2 \le k$ and $2k < n$; \emph{right-interior} if
$2 \le n-k$ and $n < 2k$. Let $L(t)$ count the left-interior occurrences and $Z(t)$ the central
ones.
\end{definition}

\begin{definition}[Folded column index]
For $k \le n$ put $\fold(n,k) = \min(k, n-k)$. Rows are unimodal:
$\binom{n}{j} \le \binom{n}{k}$ whenever $\fold(n,j) \le \fold(n,k)$.
\end{definition}

\begin{lemma}[Column uniqueness]\label{lem:coluniq}
For fixed $k \ge 2$ the map $n \mapsto \binom{n}{k}$ is strictly increasing on $n \ge k$.
Consequently two occurrences of the same value in the same column coincide, and at most two
occurrences share a given folded index.
\end{lemma}

\begin{proof}[Proof sketch]
$\binom{n+1}{k} - \binom{n}{k} = \binom{n}{k-1} > 0$ for $k \ge 1$, $n \ge k$.
\end{proof}

\begin{lemma}[Central uniqueness]\label{lem:centuniq}
$Z(t) \le 1$.
\end{lemma}

\begin{proof}[Proof sketch]
$\binom{2c+2}{c+1} = \frac{2(2c+1)}{c+1}\binom{2c}{c} > \binom{2c}{c}$, so the central binomial
coefficients are strictly increasing.
\end{proof}

\begin{proposition}[Reflection decomposition]\label{prop:refl}
For $t \ge 3$,
\[
N(t) = 2 + 2L(t) + Z(t), \qquad Z(t) \in \{0,1\}.
\]
\end{proposition}

\begin{proof}[Proof sketch]
The boundary occurrences of $t \ge 3$ are exactly $(t,1)$ and $(t,t-1)$. The mirror
$(n,k) \mapsto (n,n-k)$ is a fixed-point-free involution between left- and right-interior
occurrences. Central occurrences are the fixed points, and there is at most one by
Lemma~\ref{lem:centuniq}.
\end{proof}

\begin{corollary}[Parity]
$N(t)$ is even unless $t$ is a central binomial coefficient $\binom{2c}{c}$ with $c \ge 2$.
\end{corollary}

Thus $N(6) = N(20) = N(70) = 3$, corresponding to $\binom{4}{2}, \binom{6}{3}, \binom{8}{4}$.
An exhaustive scan confirms the prediction sharply: the integers of odd multiplicity below
$10^7$ are exactly $6, 20, 70, 252, 924, 3432, 12870, 48620, 184756, 705432, 2704156$, the
central binomial coefficients, each of multiplicity exactly three. The corollary reduces
``$N(t) \notin \{5,7\}$'' to a statement about central binomial coefficients.

\section{The smoothness hierarchy}\label{sec:smooth}

\begin{lemma}[Arithmetic input]\label{lem:arith}
If $p$ is prime, $k \le n$ and $p \mid \binom{n}{k}$, then $p \le n$.
\end{lemma}

\begin{proof}[Proof sketch]
$\binom{n}{k}\,k!\,(n-k)! = n!$, so $p \mid n!$ and hence $p \le n$.
\end{proof}

\begin{lemma}[Geometric input]\label{lem:geom}
If $\binom{n}{k} = t$ with $2 \le k$ and $k+2 \le n$, then $n(n-1) \le 2t$.
\end{lemma}

\begin{proof}[Proof sketch]
Unimodality gives $\binom{n}{2} \le \binom{n}{k} = t$, and $2\binom{n}{2} = n(n-1)$.
\end{proof}

\begin{theorem}[Multiplicity two from a large prime factor]\label{thm:largeprime}
Let $t \ge 3$ and let $p$ be a prime with $p \mid t$ and $2t < p(p-1)$. Then $N(t) = 2$.
\end{theorem}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:refl} it suffices to show $L(t) = Z(t) = 0$. Any left-interior or
central occurrence $(n,k)$ has $2 \le k$ and $k+2 \le n$. Lemmas~\ref{lem:arith}
and~\ref{lem:geom} give $p \le n$ and $n(n-1) \le 2t$, so $p(p-1) \le 2t$, contradicting the
hypothesis.
\end{proof}

\begin{theorem}[Smoothness theorem]\label{thm:smooth}
If $t \ge 3$ and $N(t) \ge 3$, then every prime factor $p$ of $t$ satisfies $p(p-1) \le 2t$,
hence $p \le \sqrt{2t}+1$.
\end{theorem}

\begin{proof}[Proof sketch]
Contrapositive of Theorem~\ref{thm:largeprime}; if $p > \sqrt{2t}+1$ then
$p(p-1) \ge (\lfloor\sqrt{2t}\rfloor+1)^2 > 2t$.
\end{proof}

\begin{corollary}[Families of multiplicity two]\label{cor:families}
For every $c \ge 1$ and every prime $p > 2c+1$ we have $N(cp) = 2$. In particular $N(p) = 2$
for primes $p \ge 5$ and $N(2p) = 2$ for primes $p \ge 7$.
\end{corollary}

\begin{proof}[Proof sketch]
$2t = 2cp < (p-1)p$ because $2c < p-1$; apply Theorem~\ref{thm:largeprime}.
\end{proof}

\begin{corollary}
For every $c \ge 1$ the set $\{t : N(t) = 2,\ c \mid t\}$ is infinite.
\end{corollary}

\begin{proof}[Proof sketch]
Apply Corollary~\ref{cor:families} to arbitrarily large primes $p$.
\end{proof}

\begin{lemma}[A deep column exists]\label{lem:deepcol}
Let $t \ge 3$, $m \ge 1$ and $N(t) \ge 2m+2$. Then there is an occurrence $\binom{n}{k} = t$
with $2k < n$ and $k \ge m+1$.
\end{lemma}

\begin{proof}[Proof sketch]
Proposition~\ref{prop:refl} and Lemma~\ref{lem:centuniq} give $L(t) \ge m$. By
Lemma~\ref{lem:coluniq} the corresponding columns are pairwise distinct and all $\ge 2$; they
cannot all lie in $\{2,\dots,m\}$, a set of size $m-1$.
\end{proof}

\begin{theorem}[Smoothness hierarchy]\label{thm:hierarchy}
Let $t \ge 3$, $m \ge 1$, $N(t) \ge 2m+2$, and let $p$ be a prime with $p \mid t$. Then
$\binom{p}{m+1} \le t$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $(n,k)$ from Lemma~\ref{lem:deepcol}. Lemma~\ref{lem:arith} gives $p \le n$, so
$\binom{p}{m+1} \le \binom{n}{m+1}$; since $m+1 \le k$ and $2k < n$, unimodality gives
$\binom{n}{m+1} \le \binom{n}{k} = t$.
\end{proof}

\begin{corollary}[Quantitative hierarchy]
Under the hypotheses of Theorem~\ref{thm:hierarchy},
\[
(p-m)^{m+1} \le (m+1)!\,t, \qquad\text{i.e.}\qquad p \le m + \big((m+1)!\,t\big)^{1/(m+1)}.
\]
\end{corollary}

\begin{proof}[Proof sketch]
$(p-m)^{m+1} \le p^{\underline{m+1}} = (m+1)!\binom{p}{m+1} \le (m+1)!\,t$.
\end{proof}

\begin{corollary}[Level $m=2$]
If $N(t) \ge 6$ then $p(p-1)(p-2) \le 6t$ for every prime $p \mid t$; such $t$ is essentially
$t^{1/3}$-smooth.
\end{corollary}

\begin{example}[The champion]
$N(3003) = 8 = 2\cdot 3 + 2$, so Theorem~\ref{thm:hierarchy} with $m = 3$ gives
$\binom{p}{4} \le 3003$ for every prime $p \mid 3003$. Since $\binom{18}{4} = 3060 > 3003$,
every prime factor of $3003$ is at most $17$; indeed $3003 = 3\cdot7\cdot11\cdot13$.
\end{example}

\section{Density: almost every number occurs exactly twice}\label{sec:density}

\begin{definition}
$\mathcal{E}(X) = \{t : 2 \le t \le X,\ N(t) \ge 3\}$.
\end{definition}

\begin{lemma}\label{lem:interior}
If $t \ge 3$ and $N(t) \ge 3$ then $t$ has an occurrence $\binom{n}{k} = t$ with $2 \le k$ and
$2k \le n$.
\end{lemma}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:refl}, $N(t) \ge 3$ forces $L(t) \ge 1$ or $Z(t) = 1$.
\end{proof}

\begin{theorem}[Counting bound]\label{thm:count}
For all $X$,
\[
\#\mathcal{E}(X) \le \big(\lfloor\sqrt{2X}\rfloor + 2\big)\big(\lfloor\log_2 X\rfloor + 1\big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
For $t \in \mathcal{E}(X)$ take $(n,k)$ from Lemma~\ref{lem:interior}. Lemma~\ref{lem:geom}
gives $n \le \sqrt{2X}+1$, and $2^k \le \binom{n}{k} = t \le X$ gives $k \le \log_2 X$. Thus
$\mathcal{E}(X)$ lies in the image of an explicit box under $(n,k) \mapsto \binom{n}{k}$.
\end{proof}

\begin{corollary}[Density one]
For every constant $c$ there is $N_c$ with $c\,\#\mathcal{E}(X) \le X$ for all $X \ge N_c$;
one may take $N_c = (21c+21)^4 + 16$. Hence $\{t : N(t) = 2\}$ has natural density one.
\end{corollary}

\begin{remark}
At $X = 10^6$ the bound gives $28\,320$, while the true count is $1\,732$; at $X = 10^7$ it
gives $107\,376$ against a true count of $5\,125$.
\end{remark}

\section{A factor-two sharpening of the logarithmic bound}\label{sec:log}

\begin{lemma}[Row pigeonhole]\label{lem:pigeon}
For all $b$, $4^b \le (2b+1)\binom{2b}{b}$.
\end{lemma}

\begin{proof}[Proof sketch]
The $2b+1$ entries of row $2b$ sum to $4^b$ and none exceeds the central entry.
\end{proof}

\begin{lemma}\label{lem:centdom}
If $\binom{n}{k} = t$ and $b = \fold(n,k)$, then $\binom{2b}{b} \le t$.
\end{lemma}

\begin{proof}[Proof sketch]
$2b \le n$ and $\binom{n}{b} = t$, so $\binom{2b}{b} \le \binom{n}{b} = t$.
\end{proof}

\begin{lemma}\label{lem:foldbound}
If $t \ge 2$ and $\binom{n}{k} = t$ with $b = \fold(n,k)$, then $4^b \le (2\log_2 t + 1)t$, so
$b \le \tfrac12\log_2\big((2\log_2 t + 1)t\big)$.
\end{lemma}

\begin{theorem}[Sharpened bound]\label{thm:sharplog}
For $t \ge 2$,
\[
N(t) \le \log_2\!\big((2\log_2 t + 1)\,t\big) \le \log_2 t + \log_2(2\log_2 t + 1) + 1 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Split $\Occ(t)$ into the (at most two) occurrences of folded index $\le 1$ and the rest. Each
remaining folded index lies in $[2,M]$ with
$M = \lfloor\tfrac12\log_2((2\log_2 t+1)t)\rfloor$ by Lemma~\ref{lem:foldbound}, and carries at
most two occurrences by Lemma~\ref{lem:coluniq}. Hence $N(t) \le 2 + 2(M-1) = 2M$.
\end{proof}

\begin{corollary}
For $t \ge 2^{16}$, $N(t) < 2\log_2 t$.
\end{corollary}

\begin{proof}[Proof sketch]
With $L = \lfloor\log_2 t\rfloor \ge 16$ one has $2L+1 < 2^{L-2}$, hence
$\log_2(2L+1) \le L-3$, and Theorem~\ref{thm:sharplog} gives $N(t) \le 2L-2$.
\end{proof}

