\section{Sharp thresholds}\label{sec:thresholds}

\begin{theorem}[Growth threshold]\label{thm:growth}
If $t \ge 3$, $m \ge 1$ and $N(t) \ge 2m+2$, then $t \ge \binom{2m+3}{m+1}$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $(n,k)$ from Lemma~\ref{lem:deepcol}: $k \ge m+1$ and $n > 2k$, so $n \ge 2m+3$, whence
$\binom{2m+3}{m+1} \le \binom{n}{m+1} \le \binom{n}{k} = t$.
\end{proof}

\begin{lemma}[Two interior columns are expensive]\label{lem:twocol}
Suppose $\binom{n}{j} = \binom{m}{k} = t$ with $2 \le j < k$, $2j < n$, $2k < m$. Then either
$k \ge 4$ and $t \ge \binom{9}{4} = 126$, or $k = 3$, $j = 2$, and $t$ is simultaneously of the
form $\binom{m}{3}$ with $m \ge 7$ and $\binom{n}{2}$.
\end{lemma}

\begin{theorem}[Sharp thresholds]\label{thm:thresholds}
The least $t \ge 2$ with $N(t) \ge 3$ is $6$; with $N(t) \ge 4$ is $10$; with $N(t) \ge 6$ is
$120$; with $N(t) \ge 8$ is $3003$.
\end{theorem}

\begin{proof}[Proof sketch]
Attainment is direct computation. For minimality of $120$: $N(t) \ge 6$ forces $L(t) \ge 2$,
so Lemma~\ref{lem:twocol} applies. In the first case $t \ge 126 > 120$. In the second,
$t = \binom{m}{3}$ with $m \ge 7$ and $t$ triangular; below $120$ the only candidates are
$35, 56, 84$, none of which is triangular, so $t \ge 120$. The case $N(t) \ge 8$ runs the same
descent one level deeper, with three interior columns, leaving a finite explicit check.
\end{proof}

\section{Adjacent repetitions: complete classification}\label{sec:adjacent}

\begin{definition}
A pair $(n,k)$ with $1 \le k$ and $k+2 \le n$ is an \emph{adjacent repetition} if
$\binom{n}{k} = \binom{n-1}{k+1}$.
\end{definition}

\begin{proposition}\label{prop:adjsix}
If $2 \le k$, $k+3 < n-k$ and $\binom{n}{k} = \binom{n-1}{k+1}$, then
$N\big(\binom{n}{k}\big) \ge 6$: the six positions
$(n,k), (n,n-k), (n-1,k+1), (n-1,n-k-2), (t,1), (t,t-1)$ are pairwise distinct.
\end{proposition}

\subsection{From combinatorics to a norm form}

\begin{lemma}\label{lem:clear}
For $1 \le k$ and $k+2 \le n$,
\[
\binom{n}{k} = \binom{n-1}{k+1} \iff n(k+1) = (n-k)(n-k-1).
\]
\end{lemma}

\begin{proof}[Proof sketch]
Write $n = m+1$ and use $\binom{m}{k}(m+1) = \binom{m+1}{k}(m+1-k)$ together with
$\binom{m}{k+1}(k+1) = \binom{m}{k}(m-k)$ to clear factorials.
\end{proof}

\begin{lemma}\label{lem:norm}
Let $u = n-k \ge 2$ satisfy $n(n-u+1) = u(u-1)$. Put $N = 5n+1$ and $U = 5u-3$. Then
\[
N^2 - NU - U^2 = -5 .
\]
\end{lemma}

The form $x^2 - xy - y^2$ is the norm form of $\ZZ[\varphi]$, $\varphi = (1+\sqrt5)/2$.

\begin{lemma}[Lucas pairs solve the form]\label{lem:lucsol}
For all $i \ge 0$, $L_{i+1}^2 - L_{i+1}L_i - L_i^2 = 5(-1)^{i+1}$.
\end{lemma}

\begin{theorem}[Descent]\label{thm:descent}
If $x, y \in \NN$ satisfy $x^2 - xy - y^2 = \pm 5$, then $x = L_{i+1}$ and $y = L_i$ for some
$i \ge 0$.
\end{theorem}

\begin{proof}[Proof sketch]
Strong induction on $x$. The map $(x,y) \mapsto (y, x-y)$ negates the form; $x \ne y$ because
$5$ is not a perfect square; and $x > y$ makes the descent strictly decrease $x$. The terminal
solutions are $(1,2) = (L_1,L_0)$ and $(3,1) = (L_2,L_1)$; reversing the descent reconstructs
$(L_{i+1},L_i)$.
\end{proof}

\begin{lemma}[Index selection]\label{lem:mod5}
$L_j \bmod 5$ is periodic of period $4$, taking the values $2,1,3,4$ for
$j \equiv 0,1,2,3 \pmod 4$. In particular $L_j \equiv 2 \pmod 5$ forces $4 \mid j$.
\end{lemma}

\begin{theorem}[Classification in Lucas form]\label{thm:lucasclass}
For $1 \le k$ and $k+2 \le n$,
\[
\binom{n}{k} = \binom{n-1}{k+1}
\iff
\exists j \ge 0 : \ 5n+1 = L_{4j+9} \ \text{ and }\ 5(n-k) = L_{4j+8}+3 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Lemmas~\ref{lem:clear} and~\ref{lem:norm} produce a solution of $N^2-NU-U^2 = -5$;
Theorem~\ref{thm:descent} makes it a consecutive Lucas pair; the sign together with the
congruences $N \equiv 1$, $U \equiv 2 \pmod 5$ and Lemma~\ref{lem:mod5} force the index to be
$4j+8$. The converse reverses the substitutions.
\end{proof}

\begin{corollary}\label{cor:small}
The only adjacent repetitions with $n \le 700$ are $(15,5)$ and $(104,39)$; and $3003$ is the
only value $\binom{n}{k} < 10^6$ arising from an adjacent repetition.
\end{corollary}

\subsection{The Lucas--Fibonacci dictionary via Cassini}

\begin{theorem}[Cassini's identity]\label{thm:cassini}
For all $a \ge 0$, $F_{a+1}^2 - F_aF_{a+2} = (-1)^a$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $a$: substituting $F_{a+3} = F_{a+1}+F_{a+2}$ and $F_{a+2} = F_a+F_{a+1}$ into
$F_{a+2}^2 - F_{a+1}F_{a+3}$ yields $-(F_{a+1}^2 - F_aF_{a+2})$.
\end{proof}

\begin{theorem}[Dictionary]\label{thm:dict}
For all $a \ge 0$,
\[
L_{2a} = 5F_a^2 + 2(-1)^a, \qquad L_{2a+1} = 5F_aF_{a+1} + (-1)^a .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Simultaneous induction on $a$, with base $L_0 = 2$, $L_1 = 1$. The inductive step reduces,
after substituting $L_{2a+2} = L_{2a}+L_{2a+1}$, $L_{2a+3} = L_{2a+1}+L_{2a+2}$ and
$F_{a+2} = F_a+F_{a+1}$, exactly to Cassini's identity (Theorem~\ref{thm:cassini}) at
index $a$.
\end{proof}

Write $R_i = F_{2i+4}F_{2i+5}$ and $C_i = F_{2i+2}F_{2i+5}$.

\begin{lemma}[Family in Lucas coordinates]\label{lem:famluc}
For all $i \ge 0$,
\[
5R_i + 1 = L_{4i+9}, \qquad R_i - C_i = F_{2i+3}F_{2i+5}, \qquad 5(R_i - C_i) = L_{4i+8}+3 .
\]
Moreover $C_i \ge 1$ and $C_i + 2 \le R_i$.
\end{lemma}

\begin{proof}[Proof sketch]
The first identity is Theorem~\ref{thm:dict} at $a = 2i+4$ in the odd case, with
$(-1)^{2i+4} = 1$. The second is $F_{2i+4} = F_{2i+2}+F_{2i+3}$. The third combines
Theorem~\ref{thm:dict} at $a = 2i+4$ in the even case with Cassini at index $2i+3$, which reads
$F_{2i+3}F_{2i+5} = F_{2i+4}^2 + 1$.
\end{proof}

\begin{theorem}[Completeness of the Fibonacci family]\label{thm:complete}
For $1 \le k$ and $k+2 \le n$,
\[
\binom{n}{k} = \binom{n-1}{k+1}
\iff
\exists i \ge 0 : \ n = F_{2i+4}F_{2i+5} \ \text{ and }\ k = F_{2i+2}F_{2i+5}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) Lemma~\ref{lem:famluc} supplies the Lucas certificate of
Theorem~\ref{thm:lucasclass} with $j = i$. ($\Rightarrow$) Theorem~\ref{thm:lucasclass} gives
$j$ with $5n+1 = L_{4j+9}$ and $5(n-k) = L_{4j+8}+3$; comparing with
Lemma~\ref{lem:famluc} at $i = j$ yields $n = R_j$ and then $k = C_j$.
\end{proof}

\begin{corollary}[The complete list]
The adjacent repetitions in Pascal's triangle are exactly
\[
(15,5),\ (104,39),\ (714,272),\ (4895,1869),\ (33552,12815),\ (229970,87840),\ \dots
\]
and no others. Each yields a value of multiplicity at least $6$, so there are infinitely many
integers of multiplicity $\ge 6$; the smallest is $\binom{15}{5} = 3003$.
\end{corollary}

\begin{remark}
Other sources of multiplicity six exist: the complete list of $t \le 10^7$ with $N(t) = 6$ is
$120, 210, 1540, 7140, 11628, 24310$, all \emph{non-adjacent} coincidences, for instance
$120 = \binom{16}{2} = \binom{10}{3}$, $210 = \binom{21}{2} = \binom{10}{4}$ and
$1540 = \binom{56}{2} = \binom{22}{3}$. But the adjacent mechanism, the only one currently
known to be infinite, is now completely understood.
\end{remark}

\section{Algorithms}

\paragraph{Multiplicity by bounded enumeration.}
To compute $N(t)$, scan rows $2 \le n \le t$, breaking early within each row by unimodality.
Lemma~\ref{lem:geom} confines the interior occurrences to $n \le \sqrt{2t}+1$, so all interior
occurrences can be found in $O(\sqrt t\,\log t)$ big-integer operations.

\paragraph{Smoothness certificate.}
Factor $t$ and, for each prime factor $p$ and level $m$, test $\binom{p}{m+1} \le t$. By
Theorem~\ref{thm:hierarchy} the first failing level certifies $N(t) \le 2m+1$.

\paragraph{Enumeration of adjacent repetitions.}
Iterate the Fibonacci recursion and output $(F_{2i+4}F_{2i+5}, F_{2i+2}F_{2i+5})$; by
Theorem~\ref{thm:complete} this is complete, at $O(1)$ big-integer operations per member.

\section{Discussion and future directions}

\begin{conjecture}[Grand challenge]
There is an absolute $m_0$ with $N(t) < 2m_0+2$ for all $t \ge 2$; concretely $N(t) \le 8$ for
all $t \ge 2$, with equality only at $t = 3003$.
\end{conjecture}

Theorem~\ref{thm:hierarchy} converts multiplicity into smoothness: $N(t) \ge 2m+2$ forces
$\binom{p}{m+1} \le t$ for every prime $p \mid t$, so $t$ must be $t^{1/(m+1)}$-smooth.
Combining this with a lower bound on the number of prime factors needed to build $t$ from small
primes ($\Omega(t) \gg \log t/\log\log t$) should close the gap between ``smooth'' and
``impossible''. Theorem~\ref{thm:growth} and the sharp thresholds of
Theorem~\ref{thm:thresholds} give the quantitative shape at the bottom of the range. A single
counterexample --- an explicit $t$ with nine or more representations --- would refute the
conjecture.

\begin{conjecture}
For every $t \ge 2$, $N(t) \notin \{5,7\}$.
\end{conjecture}

By Proposition~\ref{prop:refl} and Lemma~\ref{lem:centuniq}, odd multiplicity requires
$t = \binom{2c}{c}$, so the conjecture reduces to: no central binomial coefficient has two (or
three) further non-central occurrences. This is a Diophantine problem of the same shape as
Theorem~\ref{thm:lucasclass}, which yielded completely to descent; the same template --- reduce
to a Pell-like form, classify solutions by a Lucas/Fibonacci recursion --- can be
re-instantiated.

\paragraph{Further directions.}
\begin{itemize}[leftmargin=*]
\item \emph{Uniqueness of $3003$.} Is $3003$ the only integer with $N(t) = 8$?
Corollary~\ref{cor:small} shows the next adjacent repetition has $29$ digits.
\item \emph{Non-adjacent infinite families.} Are there infinitely many $t$ with $N(t) \ge 6$
from non-adjacent column coincidences? Each fixed column pair $(j,k)$ gives a curve
$\binom{n}{j} = \binom{m}{k}$ with, typically, finitely many integral points.
\item \emph{Sharpening the counting bound.} Restricting the admissible box by
Theorem~\ref{thm:smooth} should lower the logarithmic factor in Theorem~\ref{thm:count}.
\item \emph{Improving the logarithmic bound.} The pigeonhole of Lemma~\ref{lem:pigeon} is nearly
sharp; the remaining loss is the crude ``two occurrences per folded index''.
\end{itemize}

\section{Conclusion}

A reflection symmetry makes multiplicity even away from the central column, so odd
multiplicities are a central-binomial phenomenon. A cross-cut between the geometry of the
triangle (interior entries cap their row) and the arithmetic of factorials (prime factors cap at
the row index) yields a hierarchy: the more often a number appears, the smoother and the larger
it must be. Counting the resulting admissible box shows the exceptional numbers have density
zero, and a free pigeonhole halves the constant in the classical logarithmic bound. Finally,
the principal known source of multiplicity six is completely classified: it occurs exactly at
the Fibonacci pairs $\big(F_{2i+4}F_{2i+5},\, F_{2i+2}F_{2i+5}\big)$, via the norm form
$x^2-xy-y^2 = \pm 5$, descent to consecutive Lucas numbers, and a dictionary powered by
Cassini's identity.

