function MULTIPLICITY(t):
    require t >= 2
    P <- empty set of positions
    if t = 2 then add (2,1) to P else add (t,1) and (t,t-1) to P
    n <- 4
    while n*(n-1) <= 2t do            # geometric row bound
        for k <- 2 to floor(n/2) do
            v <- C(n,k)
            if v > t then break        # unimodality
            if v = t then
                add (n,k) to P
                if 2k != n then add (n, n-k) to P
        n <- n + 1
    return (|P|, sorted P)

function REFLECTION_DECOMPOSITION(t):
    (N, P) <- MULTIPLICITY(t)
    L <- #{(n,k) in P : k >= 2 and 2k < n}
    Z <- #{(n,k) in P : k >= 2 and n = 2k}
    assert N = 2 + 2L + Z and Z <= 1
    return (N, L, Z)
